BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS platform;
CREATE TABLE platform.schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now(), checksum text NOT NULL);
CREATE TABLE platform.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, status text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), revision bigint NOT NULL DEFAULT 1);
CREATE TABLE platform.tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES platform.organizations(id), parent_tenant_id uuid REFERENCES platform.tenants(id), name text NOT NULL, region text NOT NULL, status text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), revision bigint NOT NULL DEFAULT 1);
CREATE TABLE platform.domain_objects(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), object_type text NOT NULL, status text NOT NULL DEFAULT 'active', schema_version text NOT NULL DEFAULT '1.0', data jsonb NOT NULL DEFAULT '{}', labels jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id));
CREATE INDEX domain_objects_type_idx ON platform.domain_objects(tenant_id,object_type,updated_at DESC,id);
CREATE TABLE platform.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_subject text NOT NULL, display_name text NOT NULL, email text, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(external_subject));
CREATE TABLE platform.roles(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), name text NOT NULL, permissions jsonb NOT NULL, conditions jsonb NOT NULL DEFAULT '{}', revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,name));
CREATE TABLE platform.role_grants(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), principal_id text NOT NULL, role_id uuid NOT NULL, scope jsonb NOT NULL, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, revoked_at timestamptz, PRIMARY KEY(tenant_id,id));
CREATE TABLE platform.api_credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), principal_id text NOT NULL, secret_hash text NOT NULL, scopes jsonb NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE platform.refresh_tokens(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES platform.tenants(id), principal_id text NOT NULL, token_hash text NOT NULL, family_id uuid NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, revoked_at timestamptz);
CREATE TABLE platform.endpoints(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), device_identity text NOT NULL, hostname text, os_type text NOT NULL, os_version text, architecture text, health text NOT NULL, last_seen_at timestamptz, data jsonb NOT NULL DEFAULT '{}', revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,device_identity));
CREATE TABLE platform.agents(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, endpoint_id uuid, instance_id text NOT NULL, version text NOT NULL, capabilities jsonb NOT NULL, public_key text, status text NOT NULL, last_checkin timestamptz, revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,endpoint_id) REFERENCES platform.endpoints(tenant_id,id), UNIQUE(tenant_id,instance_id));
CREATE TABLE platform.policies(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), name text NOT NULL, status text NOT NULL, current_version_id uuid, revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id));
CREATE TABLE platform.policy_versions(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, policy_id uuid NOT NULL, version integer NOT NULL, content jsonb NOT NULL, content_hash text NOT NULL, status text NOT NULL, compatibility jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,policy_id) REFERENCES platform.policies(tenant_id,id), UNIQUE(tenant_id,policy_id,version));
CREATE TABLE platform.raw_events(id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES platform.tenants(id), source text NOT NULL, received_at timestamptz NOT NULL, payload_ref text NOT NULL, payload_hash text NOT NULL, parser_hint text, PRIMARY KEY(tenant_id,id,received_at)) PARTITION BY RANGE(received_at);
CREATE TABLE platform.raw_events_default PARTITION OF platform.raw_events DEFAULT;
CREATE TABLE platform.telemetry_events(id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES platform.tenants(id), event_time timestamptz NOT NULL, kind text NOT NULL, category text[] NOT NULL, action text NOT NULL, source jsonb NOT NULL, normalization jsonb NOT NULL, entities jsonb NOT NULL DEFAULT '{}', raw_event_id uuid NOT NULL, data jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(tenant_id,id,event_time)) PARTITION BY RANGE(event_time);
CREATE TABLE platform.telemetry_events_default PARTITION OF platform.telemetry_events DEFAULT;
CREATE INDEX telemetry_event_time_idx ON platform.telemetry_events(tenant_id,event_time DESC,id);
CREATE TABLE platform.detection_rules(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), format text NOT NULL, name text NOT NULL, status text NOT NULL, current_version integer, data jsonb NOT NULL, revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id));
CREATE TABLE platform.findings(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), rule_id uuid, severity integer NOT NULL, confidence integer NOT NULL, status text NOT NULL, evidence_refs jsonb NOT NULL, reason jsonb NOT NULL, first_seen timestamptz NOT NULL, last_seen timestamptz NOT NULL, revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id));
CREATE TABLE platform.incidents(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), title text NOT NULL, severity integer NOT NULL, status text NOT NULL, finding_ids jsonb NOT NULL, correlation_reason jsonb NOT NULL, first_seen timestamptz NOT NULL, last_seen timestamptz NOT NULL, revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id));
CREATE TABLE platform.cases(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), workspace_id uuid, title text NOT NULL, status text NOT NULL, severity integer NOT NULL, owner text, classification text NOT NULL, data jsonb NOT NULL DEFAULT '{}', revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id));
CREATE TABLE platform.jobs(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), job_type text NOT NULL, idempotency_key text NOT NULL, state text NOT NULL, target jsonb NOT NULL, parameters jsonb NOT NULL, result jsonb, attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,idempotency_key));
CREATE TABLE platform.evidence(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), object_ref text NOT NULL, manifest jsonb NOT NULL, sha256 text NOT NULL, custody_state text NOT NULL, classification text NOT NULL, legal_hold boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id));
CREATE TABLE platform.custody_events(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, evidence_id uuid NOT NULL, action text NOT NULL, actor text NOT NULL, occurred_at timestamptz NOT NULL, prior_hash text, record_hash text NOT NULL, data jsonb NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,evidence_id) REFERENCES platform.evidence(tenant_id,id));
CREATE TABLE platform.plugin_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id text NOT NULL, version text NOT NULL, digest text NOT NULL, manifest jsonb NOT NULL, signature text NOT NULL, status text NOT NULL, UNIQUE(package_id,version));
CREATE TABLE platform.plugin_installations(id uuid NOT NULL DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), package_id uuid NOT NULL REFERENCES platform.plugin_packages(id), granted_permissions jsonb NOT NULL, configuration_ref text, status text NOT NULL, revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id));
CREATE TABLE platform.audit_events(id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES platform.tenants(id), occurred_at timestamptz NOT NULL, actor jsonb NOT NULL, action text NOT NULL, resource jsonb NOT NULL, decision text NOT NULL, outcome text NOT NULL, request_id text NOT NULL, before_hash text, after_hash text, data jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(tenant_id,id,occurred_at)) PARTITION BY RANGE(occurred_at);
CREATE TABLE platform.audit_events_default PARTITION OF platform.audit_events DEFAULT;
CREATE TABLE platform.outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES platform.tenants(id), topic text NOT NULL, message jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0);
INSERT INTO platform.schema_migrations(version,checksum) VALUES ('0001_sprint_zero','generated-at-build') ON CONFLICT(version) DO NOTHING;
COMMIT;
